    merged_list = []
    i = j = 0
    while i < n and j < n:
        if list1[i] <= list2[j]:
            merged_list.append(list1[i])
            i += 1
        else:
            merged_list.append(list2[j])
            j += 1
    # Append remaining elements from either list
    while i < n:
        merged_list.append(list1[i])
        i += 1
    while j < n:
        merged_list.append(list2[j])
        j += 1
    # Return median of the merged list
    if n == 0:
        return 0.0
    if n == 1:
        return float((list1[0] + list2[0]) / 2)
    # For odd n, median is the middle element
    # For even n, median is average of two middle elements
    if n % 2 == 1:
        return float(merged_list[n // 2])
    else:
        return float((merged_list[n // 2 - 1] + merged_list[n // 2]) / 2)
