def combinations_list(lst):
    result = []
    # Use bit manipulation to generate all possible subsets
    n = len(lst)
    for i in range(1 << n):
        subset = []
        for j in range(n):
            if i & (1 << j):
                subset.append(lst[j])
        result.append(subset)
    # Sort the result by length and then by lexicographic order
    result.sort(key=lambda x: (len(x), tuple(x)))
    return result

