    # Jacobsthal numbers follow recurrence: T(n) = T(n-1) + 2*T(n-2)
    # with T(0) = 0, T(1) = 1
    t = [0, 1, 1]
    for i in range(2, n + 1):
        next_val = t[i-1] + 2 * t[i-2]
        t.append(next_val)
    return t[n]
