def perfect_squares(start, end):
    perfect_squares = []
    # Find all perfect squares between start and end
    n = int(start ** 0.5)
    while n ** 2 <= end:
        square = n ** 2
        if start <= square <= end:
            perfect_squares.append(square)
        n += 1
    return perfect_squares

