def wind_chill(velocity, temperature):
    """Calculate the wind chill index rounded to the next integer."""
    # Formula for wind chill index in Celsius
    # Wind chill index = 13.5 + 0.61 * (T - 10) - 11.4 * (V/10) - 0.39 * (V/10)^2
    # where T is temperature in Celsius, V is wind velocity in km/h
    # The result is rounded to the nearest integer
    if velocity == 0:
        result = 13.5 + 0.61 * (temperature - 10)
    else:
        result = 13.5 + 0.61 * (temperature - 10) - 11.4 * (velocity / 10) - 0.39 * ((velocity / 10)**2)
    return round(result)
